import numpy as np

def make_batches(X, y, batch_size=32, shuffle=True, seed=None):
    if len(X) != len(y):
        raise ValueError("X and y must contain the same number of examples")
    if batch_size <= 0:
        raise ValueError("batch_size must be positive")

    rng = np.random.default_rng(seed)
    indices = np.arange(len(X))

    if shuffle:
        rng.shuffle(indices)

    for start in range(0, len(X), batch_size):
        batch_indices = indices[start:start + batch_size]
        yield X[batch_indices], y[batch_indices]

# Create a sample dataset
X = np.arange(23).reshape(-1, 1)
y = 2 * X[:, 0] + 1

for batch_number, (X_batch, y_batch) in enumerate(
    make_batches(X, y, batch_size=8, shuffle=True, seed=42),
    start=1
):
    print(
        f"Batch {batch_number}: "
        f"X shape={X_batch.shape}, "
        f"y shape={y_batch.shape}"
    )
